package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.util.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.qrcode.QRCodeWriter;
public class ArcadeActivity extends WordMazeActivity {
 ArcadeBoard game;UploadReceiver receiver;
 @Override void page(String title){if(game!=null){game.stop();game=null;}if(receiver!=null){receiver.close();receiver=null;}super.page(title);}
 @Override void home(){super.home();section("Play and share");button("Arcade and word games",()->puzzle());button("Receive images / QR upload",()->share());button("Uploaded images",()->uploads());}
 @Override void puzzle(){super.puzzle();section("Arcade");button("Drawing maze / trace the corridors",()->play(0));button("Maze Chase / Pac-Man-style",()->play(1));button("Falling Blocks / Tetris-style",()->play(2));button("Pong",()->play(3));}
 void play(int mode){String[] names={"Drawing maze","Maze Chase","Falling Blocks","Pong"};page(names[mode]);text(mode==0?"Trace from the green start to the amber exit. Stay inside corridors.":mode==1?"Collect every dot. Swipe or use arrows. Corner power dots let you catch chasers briefly.":mode==2?"Complete horizontal rows. Rotate, move, soft drop or hard drop.":"Drag your left paddle. First to 7 wins.");game=new ArcadeBoard(this,mode);body.addView(game,new LinearLayout.LayoutParams(-1,dp(440)));button("Pause / resume",()->{if(game!=null)game.paused=!game.paused;});button("Restart / new maze",()->play(mode));if(mode!=3){button(mode==2?"Rotate":"Up",()->{if(game!=null)game.direction(0);});button("Left",()->{if(game!=null)game.direction(3);});button("Right",()->{if(game!=null)game.direction(1);});button(mode==2?"Soft drop":"Down",()->{if(game!=null)game.direction(2);});if(mode==2)button("Hard drop",()->{if(game!=null)game.drop();});}text("Original small native implementations. No official Pac-Man or Tetris artwork, music or level assets. Session restarts on leaving; best scores are local.");game.start();}
 @Override public boolean onKeyDown(int key,android.view.KeyEvent event){if(game!=null){int d=key==19?0:key==22?1:key==20?2:key==21?3:-1;if(d>=0){game.direction(d);return true;}if(key==62){game.drop();return true;}}return super.onKeyDown(key,event);}
 void share(){page("Receive images");text("Choose the frame's local address. Phone and frame must share a reachable trusted LAN. No cloud or router port forwarding is needed. Transfer is unencrypted HTTP.");int count=0;try{Enumeration<NetworkInterface> nets=NetworkInterface.getNetworkInterfaces();while(nets.hasMoreElements()){NetworkInterface net=nets.nextElement();if(!net.isUp()||net.isLoopback())continue;Enumeration<InetAddress> addresses=net.getInetAddresses();while(addresses.hasMoreElements()){InetAddress address=addresses.nextElement();if(address instanceof Inet4Address&&address.isSiteLocalAddress()){button("Receive on "+address.getHostAddress(),()->receive(address));count++;}}}}catch(Exception e){toast(e.toString());}if(count==0)text("No private IPv4 address found. Connect to your home network first.");}
 void receive(InetAddress ip){page("Scan to upload");text("Trusted Wi-Fi only / unencrypted HTTP. Random session expires after 15 minutes and closes when you leave this screen or the app pauses. Anyone with the QR link on this LAN can upload. Images only, maximum 10 MiB each, 50 files / 100 MiB total.");TextView status=new TextView(this);status.setTextColor(accent);status.setTextSize(18);int stamp=revision;try{receiver=new UploadReceiver(ip,new File(getFilesDir(),"uploads"),()->ui.post(()->{if(stamp==revision)status.setText("Image received. Leave this screen to view Uploaded images.");}));String link=receiver.url();BitMatrix matrix=new QRCodeWriter().encode(link,BarcodeFormat.QR_CODE,420,420);Bitmap qr=Bitmap.createBitmap(420,420,Bitmap.Config.ARGB_8888);int[] pixels=new int[420*420];for(int y=0;y<420;y++)for(int x=0;x<420;x++)pixels[y*420+x]=matrix.get(x,y)?Color.BLACK:Color.WHITE;qr.setPixels(pixels,0,420,0,0,420,420);ImageView image=new ImageView(this);image.setImageBitmap(qr);body.addView(image,new LinearLayout.LayoutParams(-1,dp(300)));text(link);status.setText("Receiver running. Keep this screen open.");body.addView(status);button("Stop receiving",()->{if(receiver!=null){receiver.close();receiver=null;}status.setText("Receiver stopped");});button("View uploaded images (stops receiver)",()->uploads());}catch(Exception e){if(receiver!=null){receiver.close();receiver=null;}text("Could not start receiver: "+e.getMessage());}}
 void uploads(){page("Uploaded images");File dir=new File(getFilesDir(),"uploads");File[] list=dir.listFiles((d,name)->name.endsWith(".image"));if(list==null||list.length==0){text("No uploads yet.");button("Receive images",()->share());return;}Arrays.sort(list,(a,b)->Long.compare(b.lastModified(),a.lastModified()));for(File file:list)button(file.getName()+" / "+(file.length()/1024)+" KiB",()->uploaded(file));}
 void uploaded(File file){page("Uploaded image");ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(image,new LinearLayout.LayoutParams(-1,dp(430)));try{image.setImageBitmap(bitmap(read(file)));}catch(Exception e){text("Unable to decode image");}button("Back to uploads",()->uploads());button("Delete this image",()->new android.app.AlertDialog.Builder(this).setMessage("Delete this uploaded image?").setPositiveButton("Delete",(d,w)->{file.delete();uploads();}).setNegativeButton("Cancel",null).show());}
 @Override protected void onPause(){if(game!=null)game.stop();if(receiver!=null){receiver.close();receiver=null;}super.onPause();}
 @Override protected void onResume(){super.onResume();if(game!=null)game.start();}
 @Override protected void onDestroy(){if(game!=null)game.stop();if(receiver!=null)receiver.close();super.onDestroy();}
}
